/* СОКРАЩЕНИЯ. Собирает по документу аббревиатуры (ГОСТ, НИОКР, PDF) и
   сокращения с точкой (т. д., рис., см.), показывает, сколько раз каждое
   встретилось и где впервые, и вставляет «Перечень сокращений» — раздел,
   которого по ГОСТ 7.32 требуют от отчёта.

   Заодно проверка: аббревиатура, у которой в документе нигде нет расшифровки в
   скобках или через тире, — это место, где читатель спотыкается. Расшифровку
   ищем по всему тексту: «Научно-исследовательская работа (НИР)» или
   «НИР — научно-исследовательская работа».

   Ничего не отправляется наружу: сеть плагину не нужна и не разрешена. */

/* Границу слова описываем ЯВНО. \b в JavaScript построено на \w, а \w — это
   [A-Za-z0-9_]: кириллицы в нём нет, и «\bНИР\b» не совпадает никогда. */
const БУКВЫ = 'A-Za-zА-Яа-яЁё0-9_';
const НЕРАЗРЫВ = String.fromCharCode(160);
/* Аббревиатура: два и больше заглавных подряд, кириллицей или латиницей;
   внутри допускаем цифры и дефис — ГОСТ Р, ISO-9001, ЕСКД-2. */
const АББР = new RegExp('(^|[^' + БУКВЫ + '])([А-ЯЁ]{2,}(?:-[А-ЯЁ0-9]+)*|[A-Z]{2,}(?:-[A-Z0-9]+)*)(?![' + БУКВЫ + '])', 'g');
/* Сокращение с точкой: «рис.», «см.», «стр.», «т. д.» — одно-два слова из 1–4
   строчных букв с точкой. Пробел между ними бывает и неразрывным. */
const СОКР = new RegExp('(^|[^' + БУКВЫ + '])([а-яё]{1,4}\\.(?:[ ' + НЕРАЗРЫВ + '][а-яё]{1,4}\\.)?)', 'g');
/* Заглавными набирают и обычные слова — эти за сокращения не считаем. */
const НЕ_АББР = new Set(['ГЛАВА', 'РАЗДЕЛ', 'ПРИЛОЖЕНИЕ', 'СОДЕРЖАНИЕ', 'ВВЕДЕНИЕ', 'ЗАКЛЮЧЕНИЕ',
                         'ОГЛАВЛЕНИЕ', 'ТАБЛИЦА', 'РИСУНОК', 'ПЕРЕЧЕНЬ', 'СПИСОК', 'ИТОГО']);
const ЗАГОЛОВОК = /^H[1-6]$/;

function собрать(){
  const п = параметры({});
  const блоки = документ.блоки;
  const весь = блоки.map(б => String(б.текст || '')).join('\n');
  const найдено = new Map();                    // сокращение → {сколько, первый, вид, расшифровка}
  блоки.forEach((б, и) => {
    const т = String(б.текст || '');
    if(!т.trim()) return;
    if(п.аббревиатуры !== false){
      АББР.lastIndex = 0;
      let м;
      while((м = АББР.exec(т))){
        const с = м[2];
        if(НЕ_АББР.has(с) || с.length > 12) continue;
        учесть(найдено, с, и, 'аббревиатура');
      }
    }
    if(п.точки !== false){
      СОКР.lastIndex = 0;
      let м2;
      while((м2 = СОКР.exec(т))) учесть(найдено, м2[2].split(НЕРАЗРЫВ).join(' '), и, 'с точкой');
    }
  });
  for(const [с, о] of найдено) о.расшифровка = о.вид === 'аббревиатура' ? расшифровка(весь, с) : '';
  return [...найдено.entries()]
    .filter(([, о]) => о.сколько >= (+п.порог || 1))
    .sort((a, b) => a[0].localeCompare(b[0], 'ru'));
}
function учесть(куда, с, и, вид){
  const о = куда.get(с);
  if(о){ о.сколько++; return; }
  куда.set(с, {сколько: 1, первый: и, вид: вид, расшифровка: ''});
}
/* «Полное название (СОКР)» или «СОКР — полное название»; берём первое найденное. */
function расшифровка(весь, с){
  const экр = с.replace(/[.*+?^${}()|[\]\\-]/g, '\\$&');
  const вСкобках = new RegExp('([А-ЯЁA-Z][^.!?\\n()]{3,80}?)\\s*\\(\\s*' + экр + '\\s*\\)');
  const мс = вСкобках.exec(весь);
  if(мс) return мс[1].trim();
  const черезТире = new RegExp('(^|[^' + БУКВЫ + '])' + экр + '\\s*[—–-]\\s*([^.!?\\n]{3,80})');
  const мт = черезТире.exec(весь);
  if(мт) return мт[2].trim();
  return '';
}

/* Строка списка: «НИР · 3× · расшифровка». Из неё же достаём сокращение назад,
   когда человек выбрал строку и нажал «К первому появлению». */
const строкой = ([с, о]) => с + ' · ' + о.сколько + '×'
  + (о.вид === 'аббревиатура' ? (о.расшифровка ? ' · ' + о.расшифровка.slice(0, 40) : ' · без расшифровки') : '');
const сокращениеИз = строка => String(строка || '').split(' · ')[0];

function показать(){
  const список = собрать();
  панель.список('найдено', список.map(строкой));
  const без = список.filter(([, о]) => о.вид === 'аббревиатура' && !о.расшифровка);
  панель.сообщение(!список.length ? 'Сокращений не нашлось'
    : 'Найдено: ' + список.length
      + (без.length ? '; без расшифровки: ' + без.length + ' (' + без.slice(0, 5).map(([с]) => с).join(', ') + ')'
                    : '; все расшифрованы'));
  хранилище.положить('последних', список.length);
  return список;
}
function Обновить(){ return показать(); }
function Старт(){ показать(); }

/* К первому появлению выбранного сокращения: плагин просит, курсор ставит
   приложение — страницы у плагина нет. */
function Перейти(){
  const п = параметры({});
  const что = сокращениеИз(п.выбор || п['найдено']);
  if(!что){ панель.сообщение('Сначала выберите сокращение в списке'); return; }
  const о = собрать().find(([с]) => с === что);
  if(!о){ панель.сообщение('Сокращение «' + что + '» больше не встречается — обновите список'); return; }
  документ.перейти(о[1].первый);
  панель.сообщение(о[0] + ': впервые в абзаце ' + (о[1].первый + 1)
    + (о[1].расшифровка ? ' — ' + о[1].расшифровка : ''));
}

const эк = т => String(т == null ? '' : т).replace(/[&<>]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;'}[c]));

/* Перечень сокращений — разделом: заголовок и таблица. Уже вставленный перечень
   узнаём по заголовку и обновляем, а не плодим второй. */
async function Вставить(){
  const п = параметры({});
  const список = собрать();
  if(!список.length){ панель.сообщение('Нечего вставлять: сокращений не нашлось'); return; }
  const ЗАГ = 'Перечень сокращений';
  const блоки = документ.блоки;
  const уже = блоки.findIndex(б => ЗАГОЛОВОК.test(String(б.тег || '').toUpperCase())
    && String(б.текст || '').trim() === ЗАГ);
  if(уже >= 0 && !(await диалог.вопрос('Перечень уже есть в абзаце ' + (уже + 1) + '. Обновить его?'))){
    панель.сообщение('Перечень оставлен как был'); return;
  }
  const строки = список.map(([с, о]) => [с, о.расшифровка || '—']);
  const таблица = документ.таблица([['Сокращение', 'Расшифровка']].concat(строки), {шапка: true});
  if(уже >= 0){
    const следом = блоки[уже + 1];
    if(следом && String(следом.тег).toUpperCase() === 'TABLE') документ.правитьБлок(уже + 1, {html: таблица, тег: 'TABLE'});
    else документ.вставить(уже + 1, таблица);
    документ.перейти(уже);
    панель.сообщение('Перечень обновлён: строк ' + строки.length);
    return;
  }
  if(п.куда === 'в конец'){
    документ.вставитьВКонец('<h2>' + эк(ЗАГ) + '</h2>');
    документ.вставитьВКонец(таблица);
    документ.перейти(документ.блоки.length - 2);
  } else {
    /* в начало: сперва таблица, потом заголовок перед ней — так оба встают
       на места 0 и 1, и второй вставке не нужно знать о первой */
    документ.вставить(0, таблица);
    документ.вставить(0, '<h2>' + эк(ЗАГ) + '</h2>');
    документ.перейти(0);
  }
  панель.сообщение('Перечень вставлен: строк ' + строки.length);
}
